/**
 * @file src/types/chat.ts
 * @description Core TypeScript type definitions for the VenXR AI Chat Assistant.
 * Defines the data contracts for threads, messages, file attachments, generated files,
 * streaming events, and LangGraph agent states.
 */

/**
 * Represents the role of the message author.
 */
export type MessageRole = 'user' | 'assistant' | 'system';

/**
 * Represents the execution and delivery lifecycle of a message.
 * - 'idle': Initial stationary state.
 * - 'sending': Optimistically added to UI, awaiting API connection.
 * - 'streaming': SSE tokens actively arriving from backend.
 * - 'complete': Generation finished successfully.
 * - 'failed': Error encountered; retryable.
 */
export type MessageStatus = 'idle' | 'sending' | 'streaming' | 'complete' | 'failed';

/**
 * Supported file MIME categories for parsing and generation.
 */
export type SupportedFileType =
  | 'pdf'
  | 'docx'
  | 'xlsx'
  | 'csv'
  | 'pptx'
  | 'image'
  | 'code'
  | 'json'
  | 'text'
  | 'zip'
  | 'other';

/**
 * Metadata for a file uploaded by the user ("Any file in").
 * Strictly serializable to ensure Redux state serializability.
 */
export interface FileAttachment {
  id: string;
  name: string;
  size: number;
  type: SupportedFileType;
  mimeType: string;
  /** Summary or parsed text extracted by the file parser node */
  extractedPreview?: string;
  /** Data URL or preview link for images */
  previewUrl?: string;
  /** Status of server-side parsing */
  parseStatus: 'parsed' | 'unsupported' | 'error';
  errorMessage?: string;
}

/**
 * Metadata for a real file generated by the assistant ("Any file out").
 * Rendered as an interactive, downloadable card in the chat.
 */
export interface GeneratedFile {
  id: string;
  filename: string;
  fileType: SupportedFileType;
  mimeType: string;
  sizeBytes: number;
  downloadUrl: string;
  previewSnippet?: string;
  createdAt: string;
}

/**
 * Represents a single message in a conversation thread.
 * Kept strictly serializable for Redux store persistence.
 */
export interface ChatMessage {
  id: string;
  threadId: string;
  role: MessageRole;
  content: string;
  status: MessageStatus;
  timestamp: number;
  attachments?: FileAttachment[];
  generatedFiles?: GeneratedFile[];
  /** Error diagnostic if status === 'failed' */
  error?: {
    code: string;
    message: string;
    retryable: boolean;
  };
}

/**
 * Represents a conversation thread session.
 */
export interface ThreadMetadata {
  id: string;
  title: string;
  createdAt: number;
  updatedAt: number;
  messageCount: number;
}

/**
 * LangGraph Agent execution nodes.
 * Used for live state telemetry in the UI and interview inspector.
 */
export type LangGraphNode =
  | 'idle'
  | 'file_parser_node'
  | 'agent_node'
  | 'file_generator_node'
  | 'answer_node'
  | 'checkpointer'
  | 'error_handler';

/**
 * Structured Server-Sent Event (SSE) payload received from the backend stream.
 */
export interface SSEStreamEvent {
  event: 'token' | 'file' | 'node_transition' | 'error' | 'done';
  data: {
    token?: string;
    file?: GeneratedFile;
    node?: LangGraphNode;
    error?: string;
    threadId?: string;
    messageId?: string;
  };
}

/**
 * Normalized API error state representation for Redux.
 */
export interface ApiErrorState {
  code: string;
  message: string;
  retryable: boolean;
  timestamp: number;
}
